  'https://upload.wikimedia.org/wikipedia/commons/6/67/Haiyan_2013-11-07_1345Z_%28alternate%2C_borderless%29.png',
  TRUE,
  2
) ON CONFLICT (slug) DO NOTHING;

INSERT INTO storms (
