  affected_areas, summary, research_md, fun_facts, sources,
  og_image_url, is_featured, display_order
) VALUES (
  'typhoon-damrey-2017', 'Damrey', 'Typhoon Damrey',
  2017, '2017 Pacific', 'WP',
  2, 'Typhoon',
  NULL, NULL,
  '2017-06-01',
  NULL, NULL,
  ARRAY[]::TEXT[],
  'Typhoon Damrey, known in the Philippines as Severe Tropical Storm Ramil, was a strong tropical cyclone that affected the Philippines and Vietnam during early November 2017. Damrey first originated as a tropical depression over the Philippine archipelago of Visayas on October 31. Emerging into the South China Sea a few days later, the system strengthened into the second deadliest and twenty-third named storm of the 2017 Pacific typhoon season. Rapidly intensifying, Damrey became the season''s tent',
  '## Overview

Typhoon Damrey, known in the Philippines as Severe Tropical Storm Ramil, was a strong tropical cyclone that affected the Philippines and Vietnam during early November 2017. Damrey first originated as a tropical depression over the Philippine archipelago of Visayas on October 31. Emerging into the South China Sea a few days later, the system strengthened into the second deadliest and twenty-third named storm of the 2017 Pacific typhoon season. Rapidly intensifying, Damrey became the season''s tenth typhoon on November 3, reaching its peak intensity as a Category 2 on the same day. Damrey made landfall over Khánh Hoà, Vietnam on November 4 and began to rapidly weaken, fully dissipating on November 5.

## Key Facts

See structured data above.

## Sources

- [Wikipedia](https://en.wikipedia.org/wiki/Typhoon_Damrey_(2017))
- [NOAA NHC](https://www.nhc.noaa.gov/)
',
  ARRAY['As a Western Pacific typhoon, Damrey was named by the Japan Meteorological Agency.'],
  '[{"title":"Wikipedia — Typhoon Damrey","url":"https://en.wikipedia.org/wiki/Typhoon_Damrey_(2017)","type":"wiki"},{"title":"NOAA National Hurricane Center","url":"https://www.nhc.noaa.gov/","type":"official"}]'::JSONB,
  'https://upload.wikimedia.org/wikipedia/commons/3/3b/Damrey_2017-11-03_0507Z.jpg',
  FALSE,
  NULL
) ON CONFLICT (slug) DO NOTHING;

