  'https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Rai_2021-12-16_0159Z.jpg/3840px-Rai_2021-12-16_0159Z.jpg',
  FALSE,
  NULL
) ON CONFLICT (slug) DO NOTHING;

